import './styles.css';
import QRCode from 'qrcode';
import {CATEGORIES,STATUS,PAYMENT,METHODS,ROLES,e,money,cents,discountCents,priceInput,number,time,date,age,nextStatus,nextLabel,safeImage,totals,csvText,pixPayload} from './core.js';
import {icon} from './icons.js';
import {api,configured,demo,db,uuid,currentUser,login,logout,subscribe,upload,friendly} from './api.js';
import {demoReset} from './demo.js';
import {printReceipt} from './receipt.js';
import {kitchenBoard} from './kitchen.js';

const app=document.querySelector('#app'),overlay=document.querySelector('#overlays');
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}};
let user=null,menu=null,snapshot=null,tracked=null,publicBoard=null,poll=null,unsubscribe=null,routeSerial=0,busy=false,modal=null;
let selectedSession=null,category='Todos',search='',orderFilter='todos',orderSearch='',sound=false,audio=null,lastSync=null,connectionError='',knownPaid=null,refreshSequence=0;
let cart=read('cafe-cart',{}),staffCart={},requestId=localStorage.getItem('cafe-pending-request')||uuid();
const protectedPaths=['/admin','/caixa','/pedidos','/cozinha','/estoque','/relatorios','/equipe','/configuracoes'];
const path=()=>location.pathname.replace(/\/$/,'')||'/';
const brand=()=>`<a class="brand" href="/" data-nav><span class="brand-logo"><img src="/images/paes-cabo.png" alt="PAES Cabo"></span><span><strong>ESPAÇO CAFÉ<span class="brand-dot">.</span></strong><small>PAES CABO · À MESA, JUNTOS</small></span></a>`;
const btn=(action,label,ic='',cls='button',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${ic?icon(ic):''}${label}</button>`;
const tag=(text,cls='')=>`<span class="tag ${cls}">${text}</span>`;
const empty=(title,body,ic='coffee')=>`<div class="empty">${icon(ic)}<h3>${title}</h3><p>${body}</p></div>`;
const payTag=o=>tag(PAYMENT[o.payment_status],o.payment_status);
const statusTag=o=>tag(STATUS[o.status],o.status);
const isStaff=()=>protectedPaths.includes(path());
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;document.querySelector('#toasts').append(el);setTimeout(()=>el.remove(),5500);}
function banner(){return demo?`<div class="demo-strip">${icon('alert')} Demonstração local · pedidos e valores simulados ${btn('reset-demo','Reiniciar exemplo','','text-button')}</div>`:'';}
function connectivity(){return `<div class="sync ${navigator.onLine&&!connectionError?'':'offline'}"><i></i>${!navigator.onLine?'Sem internet':connectionError?'Sem atualização':lastSync?'Atualizado às '+time(lastSync):'Conectando'} ${btn('refresh','Atualizar','refresh','icon-button','aria-label="Atualizar dados"')}</div>`;}
async function go(url){history.pushState(null,'',url);category='Todos';search='';orderSearch='';orderFilter='todos';knownPaid=null;if(path()!=='/relatorios')selectedSession=null;await route();window.scrollTo(0,0);}
function dismiss(){if(modal){modal.close();modal.remove();modal=null;}overlay.innerHTML='';}
function dialog(title,html,submit=null,label='Salvar'){
 dismiss();const d=document.createElement('dialog');d.className='modal';d.innerHTML=`<div class="modal-head"><div><span class="eyebrow">ESPAÇO CAFÉ · PAES CABO</span><h2>${title}</h2></div>${btn('dismiss','','close','icon-button','aria-label="Fechar janela"')}</div><form class="modal-body">${html}<p class="form-error" role="alert" hidden></p>${submit?`<div class="modal-actions">${btn('dismiss','Voltar','','button subtle')}<button class="button lime" type="submit">${label} ${icon('arrow')}</button></div>`:''}</form>`;overlay.append(d);modal=d;d.showModal();d.addEventListener('click',ev=>{if(ev.target===d&&!busy)dismiss();});d.addEventListener('cancel',ev=>{if(busy)ev.preventDefault();});
 if(submit)d.querySelector('form').addEventListener('submit',async ev=>{ev.preventDefault();if(busy)return;const f=ev.currentTarget,button=f.querySelector('[type=submit]'),error=f.querySelector('.form-error');busy=true;button.disabled=true;error.hidden=true;try{await submit(new FormData(f),f);if(modal===d)dismiss();}catch(err){error.textContent=friendly(err);error.hidden=false;}finally{busy=false;if(button.isConnected)button.disabled=false;}});
 return d;
}
async function act(button,fn){if(busy)return;busy=true;if(button)button.disabled=true;try{await fn();}catch(err){toast(friendly(err),true);}finally{busy=false;if(button?.isConnected)button.disabled=false;}}
function saveCart(){localStorage.setItem('cafe-cart',JSON.stringify(cart));}
function cartEntries(isPos=false){const products=isPos?snapshot?.products:menu?.products;const basket=isPos?staffCart:cart;return Object.entries(basket).map(([id,q])=>{const p=products?.find(p=>p.id===id);return p&&Number.isInteger(q)&&q>0?{...p,quantity:q}:null;}).filter(Boolean);}
function cartTotal(isPos=false){return cartEntries(isPos).reduce((n,i)=>n+i.price_cents*i.quantity,0);}
function quantityButton(p,isPos=false){const q=(isPos?staffCart:cart)[p.id]||0;return q?`<div class="quantity">${btn('minus','', 'minus','icon-button',`data-id="${p.id}" aria-label="Diminuir ${e(p.name)}"`)}<strong>${q}</strong>${btn('add','','plus','icon-button',`data-id="${p.id}" aria-label="Adicionar ${e(p.name)}" ${q>=Math.min(p.stock,20)?'disabled':''}`)}</div>`:btn('add','Adicionar','plus','button add-button',`data-id="${p.id}" ${p.stock<1||!p.active?'disabled':''}`);}
function productCard(p,isPos=false){return `<article class="product-card ${p.stock<1?'sold-out':''}"><div class="product-picture"><img src="${e(safeImage(p.image_url,p.category))}" alt="${e(p.name)}" loading="lazy">${p.featured?tag('DA CASA','featured'):''}${p.stock<1?tag('Esgotado','sold'):p.stock<=p.low_stock?tag('Últimas unidades','low'):''}</div><div class="product-content"><span class="eyebrow">${e(p.category)} · ${p.prep_minutes||5} MIN</span><h3>${e(p.name)}</h3><p>${e(p.description||'Preparado com carinho pela nossa equipe.')}</p><div class="product-bottom"><strong>${money(p.price_cents)}</strong><span>${p.stock} disponíveis</span></div>${quantityButton(p,isPos)}<button type="button" class="text-button allergens" data-action="ingredients" data-id="${p.id}">Ingredientes e alergênicos ${icon('plus')}</button></div></article>`;}
function filters(){return `<div class="catalog-tools"><div class="pills">${['Todos',...CATEGORIES].map(c=>`<button type="button" data-action="category" data-category="${c}" class="pill ${category===c?'active':''}">${c}</button>`).join('')}</div><label class="search">${icon('search')}<input type="search" id="menu-search" placeholder="O que vai bem hoje?" value="${e(search)}" aria-label="Buscar no cardápio"></label></div>`;}
function filteredProducts(products){return products.filter(p=>(category==='Todos'||p.category===category)&&p.name.toLocaleLowerCase('pt-BR').includes(search.toLocaleLowerCase('pt-BR')));}
function productGrid(isPos=false){const list=filteredProducts((isPos?snapshot?.products.filter(p=>p.active):menu?.products)||[]);return list.length?list.map(p=>productCard(p,isPos)).join(''):empty('Nada por aqui ainda.','Explore outra categoria ou fale com a equipe.');}
function publicHeader(){const count=cartEntries().reduce((n,i)=>n+i.quantity,0);return `${banner()}<header class="public-header"><div class="container public-nav">${brand()}<nav><a href="/#cardapio">Cardápio</a><a href="/retirada" data-nav>Retirada</a><a href="/login" data-nav class="team-link">${icon('lock')} Equipe</a></nav>${btn('cart',`<span class="cart-label">Meu pedido</span> <span class="count">${count}</span>`,'bag','button cart-button')}</div></header>`;}
function renderMenu(){app.innerHTML=`${publicHeader()}<main id="main"><section class="hero"><div class="hero-photo"></div><div class="container hero-inner"><div class="hero-copy"><span class="eyebrow"><i class="live-dot"></i> UM BOM ENCONTRO PEDE UM CAFÉ</span><h1>O culto termina.<br>A mesa <em>continua.</em></h1><p>Tem café quentinho, comida feita com carinho<br>e um lugar para a nossa conversa continuar.</p><a class="button lime" href="#cardapio">Vem para a mesa ${icon('arrow')}</a><div class="hero-small">${icon('heart')} Servir também é uma forma de amar.</div></div><div class="hero-stamp">feito<br><em>para</em><br>ficar mais.</div></div></section><div class="container"><div class="service-notice"><div>${icon('coffee')}<span><strong>${menu?.session?'Nossa cozinha está por aqui.':'Nos encontramos no próximo culto.'}</strong><small>${menu?.session&&menu.settings.public_ordering?'Escolha, confirme no caixa e acompanhe seu pedido.':'Você pode conhecer o cardápio. Os pedidos abrem com a equipe.'}</small></span></div>${tag(menu?.session&&menu.settings.public_ordering?'PEDIDOS ABERTOS':'PEDIDOS PAUSADOS',menu?.session&&menu.settings.public_ordering?'paid':'pending')}</div><section id="cardapio" class="catalog"><div class="section-heading"><div><span class="eyebrow">ESCOLHA SEU FAVORITO</span><h2>O que tem de bom hoje<span class="brand-dot">?</span></h2></div><p>Do primeiro gole<br>à última boa conversa.</p></div>${filters()}<div id="product-grid" class="product-grid">${productGrid()}</div></section><section class="how-it-works"><div><span>01</span><h3>Escolha com calma.</h3><p>Monte seu pedido no celular ou diretamente no caixa.</p></div><div><span>02</span><h3>Passe no caixa.</h3><p>Confirme o pagamento com a equipe para liberar o preparo.</p></div><div><span>03</span><h3>Encontre sua senha.</h3><p>Acompanhe por aqui. Quando ficar pronto, é só retirar.</p></div></section><div class="last-orders">${lastOrderLink()}</div></div></main><footer class="public-footer container">${brand()}<span>Um espaço de cuidado. Uma mesa de encontros.</span><a href="/login" data-nav>Área da equipe ${icon('arrow')}</a></footer>`;}
function lastOrderLink(){const orders=read('cafe-my-orders',[]);return orders.length?`<h3>Já pediu por aqui?</h3>${orders.slice(0,3).map(o=>`<a class="button subtle" href="/pedido#token=${e(o.token)}" data-nav>Acompanhar #${number(o.number)} ${icon('arrow')}</a>`).join('')}`:'';}
function refreshMenuGrid(){const grid=document.querySelector('#product-grid');if(grid)grid.innerHTML=productGrid(path()==='/caixa');document.querySelectorAll('[data-action=category]').forEach(b=>b.classList.toggle('active',b.dataset.category===category));if(path()==='/caixa'){const basket=document.querySelector('#pos-basket');if(basket)basket.innerHTML=basketHTML(true);}else{const button=document.querySelector('.cart-button .count');if(button)button.textContent=cartEntries().reduce((n,i)=>n+i.quantity,0);}}
function basketHTML(isPos=false){const items=cartEntries(isPos);return `<div class="basket-items">${items.length?items.map(i=>`<div class="basket-row"><div><strong>${e(i.name)}</strong><small>${money(i.price_cents)} por unidade</small></div>${quantityButton(i,isPos)}<strong>${money(i.quantity*i.price_cents)}</strong></div>`).join(''):empty('Sua comanda começa aqui.','Toque nos produtos para adicionar ao pedido.','bag')}</div><div class="basket-summary"><span>Subtotal</span><strong>${money(cartTotal(isPos))}</strong></div><p class="muted">Retirada no Espaço Café · sem taxa de serviço</p>${btn(isPos?'counter-checkout':'checkout',isPos?'Concluir comanda':'Confirmar pedido','arrow','button lime full',items.length?'':'disabled')}`;}
function openCart(){dialog('Um pedido de coisas boas.',basketHTML());}
const discountFields=()=>`<label class="field" id="discount-field" hidden>Desconto em reais (opcional)<input name="discount" inputmode="decimal" value="0,00" placeholder="Ex.: 3,00"><small>O desconto deve ser menor que o total do pedido.</small></label><div class="checkout-total">Total a pagar <strong id="final-total"></strong></div><label class="field" id="received-field" hidden>Valor recebido em dinheiro<input name="received" inputmode="decimal" placeholder="Ex.: 20,00"></label><p id="change-value" class="notice" hidden></p>`;
function setupDiscount(total,{autofill=false}={}){
 const d=modal,method=d.querySelector('[name=method]'),discount=d.querySelector('[name=discount]'),received=d.querySelector('[name=received]');
 let receivedEdited=false;
 const update=()=>{
  const paying=Boolean(method.value),cash=method.value==='dinheiro';
  d.querySelector('#discount-field').hidden=!paying;
  d.querySelector('#received-field').hidden=!cash;
  d.querySelector('#change-value').hidden=!cash;
  try{
   const final=total-(paying?discountCents(discount.value,total):0);
   d.querySelector('#final-total').textContent=money(final);
   if(autofill&&!receivedEdited)received.value=priceInput(final);
   if(cash){
    const value=received.value.trim()?cents(received.value,{zero:true}):0;
    d.querySelector('#change-value').textContent='Troco: '+money(Math.max(0,value-final));
   }
  }catch(err){d.querySelector('#final-total').textContent='Confira o desconto';d.querySelector('#change-value').textContent=err.message;}
 };
 discount.addEventListener('input',update);
 method.addEventListener('change',update);
 received.addEventListener('input',()=>{receivedEdited=true;update();});
 update();
}
function discountSummary(o){const discount=Number(o.discount_cents)||0;return discount?`<div class="line-item"><span>Subtotal</span><strong>${money(o.total_cents+discount)}</strong></div><div class="line-item"><span>Desconto</span><strong>− ${money(discount)}</strong></div>`:'';}
async function checkout(isPos=false){const items=cartEntries(isPos),subtotal=cartTotal(isPos);if(!items.length)return;if(!isPos&&(!menu.session||!menu.settings.public_ordering))throw Error('PEDIDOS_ONLINE_PAUSADOS');if(isPos&&!snapshot.sessions.some(s=>s.state==='open'))throw Error('CAIXA_FECHADO');dialog(isPos?'Fechar esta comanda':'Como podemos te chamar?',`<p class="muted">${items.map(i=>`${i.quantity} × ${e(i.name)}`).join(' · ')}</p><div class="checkout-total">Subtotal <strong>${money(subtotal)}</strong></div><label class="field">Nome para retirada<input name="name" minlength="2" maxlength="80" autocomplete="given-name" required placeholder="Seu primeiro nome"></label><label class="field">Observação para a cozinha <span>opcional</span><textarea name="notes" maxlength="300" rows="2" placeholder="Ex.: retirar os pedidos juntos"></textarea></label>${isPos?`<label class="field">Pagamento<select name="method" id="checkout-method"><option value="">Falta pagar · registrar comanda</option>${Object.entries(METHODS).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label>${discountFields()}<p class="notice">Ao escolher Pix ou cartão, confirme antes o recebimento no banco ou na maquininha.</p>`:'<p class="notice">O preparo começa depois da confirmação do pagamento pela equipe. Seu pedido ficará reservado no estoque.</p>'}`,async f=>{
 localStorage.setItem('cafe-pending-request',requestId);
 const args={p_items:items.map(i=>({product_id:i.id,quantity:i.quantity})),p_name:f.get('name').trim(),p_notes:f.get('notes').trim(),p_request:requestId};
 if(isPos){args.p_method=f.get('method')||null;args.p_received=args.p_method==='dinheiro'?cents(f.get('received')):null;args.p_discount=args.p_method?discountCents(f.get('discount'),subtotal):0;}
 const o=await api(isPos?'cafe_counter_order_discount':'cafe_place_order',args);requestId=uuid();localStorage.removeItem('cafe-pending-request');if(isPos)staffCart={};else{cart={};saveCart();}
 const saved=read('cafe-my-orders',[]);saved.unshift({number:o.number,token:o.token});localStorage.setItem('cafe-my-orders',JSON.stringify(saved.slice(0,10)));
 dismiss();toast('Pedido #'+number(o.number)+' registrado.');if(isPos){await refreshStaff();orderDetails(o.id);}else await go('/pedido#token='+o.token);
 },isPos?'Registrar pedido':'Enviar pedido');if(isPos)setupDiscount(subtotal);}

function renderTrack(){if(!tracked){app.innerHTML=`${publicHeader()}<main class="container narrow" id="main">${empty('Encontre seu pedido.','Use o link recebido ao concluir sua comanda.','receipt')}<div class="last-orders">${lastOrderLink()}</div><a class="button lime" href="/" data-nav>Voltar ao cardápio</a></main>`;return;}const o=tracked;const current=o.payment_status==='pending'?0:({queued:1,preparing:1,ready:2,delivered:3,cancelled:0}[o.status]);app.innerHTML=`${publicHeader()}<main class="container track" id="main"><a href="/" data-nav class="back-link">← Voltar ao cardápio</a><div class="track-grid"><section><span class="eyebrow">SEU ENCONTRO ESTÁ A CAMINHO</span><h1>Oi, ${e(o.customer_name)}<span class="brand-dot">.</span></h1><p class="lead">${o.status==='cancelled'?'Seu pedido foi cancelado. Fale com a equipe se precisar.':o.payment_status==='pending'?'Passe no caixa para confirmar o pagamento.':o.status==='ready'?'Pode vir buscar. Seu pedido ficou pronto!':o.status==='delivered'?'Obrigado por ficar mais um pouquinho com a gente.':'Acompanhe aqui. A cozinha está cuidando do seu pedido.'}</p><div class="ticket-number"><small>SUA SENHA</small><strong>#${number(o.number)}</strong>${payTag(o)} ${statusTag(o)}</div>${o.status!=='cancelled'?`<ol class="timeline">${['Pedido recebido','Pagamento confirmado','Pronto para retirar','Entregue'].map((s,i)=>`<li class="${i<=current?'done':''}"><i>${i<=current?icon('check'):i+1}</i><span>${s}</span></li>`).join('')}</ol>`:`<p class="notice">${e(o.cancel_reason)}</p>`}${connectivity()}</section><aside class="panel"><h3>Sua comanda</h3>${o.items.map(i=>`<div class="line-item"><span>${i.quantity} × ${e(i.name)}</span><strong>${money(i.price_cents*i.quantity)}</strong></div>`).join('')}${discountSummary(o)}<div class="basket-summary">Total <strong>${money(o.total_cents)}</strong></div>${o.notes?`<p class="notice">${e(o.notes)}</p>`:''}${btn('print-track',o.payment_status==='paid'?'Recibo de pagamento':'Imprimir comanda','receipt','button subtle full')}${btn('share-order','Copiar link do pedido','link','button subtle full')}${o.payment_status==='pending'&&o.status!=='cancelled'?`<div id="pix-area"></div>`:''}<small class="muted">Guarde o link: ele dá acesso ao seu pedido. Não compartilhe com desconhecidos.</small></aside></div></main>`;renderPix();}
async function renderPix(){const el=document.querySelector('#pix-area');if(!el||!menu?.settings.pix_key)return;try{const s=menu.settings,payload=pixPayload(s.pix_key,s.pix_name,s.pix_city,tracked.total_cents,'CAFE'+tracked.number);const qr=await QRCode.toDataURL(payload,{width:210,margin:2,color:{dark:'#17102b',light:'#ffffff'}});if(!el.isConnected)return;el.innerHTML=`<div class="pix-card"><h3>Prefere Pix?</h3><p>Confira o favorecido no aplicativo e mostre a confirmação à equipe do caixa.</p><img src="${qr}" alt="QR Code Pix de ${money(tracked.total_cents)}"><button class="button subtle full" type="button" id="copy-pix">Copiar Pix ${icon('link')}</button><small>O pagamento não é confirmado automaticamente.</small></div>`;el.querySelector('button').onclick=()=>copy(payload);}catch(err){el.textContent=friendly(err);}}
function renderBoard(){const ready=publicBoard?.ready||[];app.innerHTML=`${banner()}<main id="main" class="pickup-board"><header>${brand()}<div>${connectivity()}${btn('fullscreen','Tela cheia','screen','button subtle')}</div></header><span class="eyebrow">UM ENCONTRO DE COISAS BOAS</span><h1>É só chegar<br>e <em>retirar.</em></h1><p>Encontre sua senha e venha buscar no balcão.</p><div class="pickup-numbers">${ready.length?ready.map(o=>`<strong>#${number(o.number)}</strong>`).join(''):'<span class="muted">Nossa cozinha está preparando os próximos pedidos.</span>'}</div><div class="preparing-line">EM PREPARO <span>${(publicBoard?.preparing||[]).map(n=>'#'+number(n)).join(' · ')||'Aguardando novos pedidos'}</span></div><footer><a href="/" data-nav>Voltar ao cardápio ${icon('arrow')}</a><small>PAES CABO · ESPAÇO CAFÉ</small></footer></main>`;}

const navItems=[['/admin','Visão geral','grid',['admin']],['/caixa','Novo pedido','plus',['admin','caixa']],['/pedidos','Pedidos','bag',['admin','caixa']],['/cozinha','Cozinha ao vivo','chef',['admin','caixa','cozinha']],['/estoque','Cardápio e estoque','box',['admin']],['/relatorios','Caixa e relatórios','chart',['admin','caixa']],['/equipe','Nossa equipe','users',['admin']],['/configuracoes','Configurações','settings',['admin']]];
function staffShell(content,title,kicker='PAES CABO · OPERAÇÃO DO CAFÉ') {const current=snapshot.sessions.find(s=>s.state==='open');app.innerHTML=`${banner()}<div class="staff-app"><aside class="sidebar">${brand()}<span class="sidebar-label">NOSSA MESA, BEM CUIDADA</span><nav>${navItems.filter(i=>i[3].includes(user.role)).map(([href,label,ic])=>`<a href="${href}" data-nav class="${path()===href?'active':''}">${icon(ic)}<span>${label}</span>${href==='/pedidos'&&totals(snapshot).pending?`<b>${totals(snapshot).pending}</b>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><a href="/" data-nav>${icon('coffee')} Ver cardápio</a><a href="/retirada" target="_blank" rel="noopener">${icon('screen')} Painel de retirada</a><div class="user-profile"><span>${e(user.email[0].toUpperCase())}</span><div><strong>${ROLES[user.role]}</strong><small>${e(user.email)}</small></div></div>${btn('logout','Sair da conta','logout','text-button')}</div></aside><div class="staff-work"><header class="staff-topbar"><div>${tag(current?'CAIXA ABERTO':'CAIXA FECHADO',current?'paid':'pending')}<span>${e(current?.title||'Prepare o próximo encontro')}</span></div>${connectivity()}</header><main id="main" class="staff-main"><div class="page-heading"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1></div><div class="heading-actions">${user.role!=='cozinha'?btn(current?'close-session':'open-session',current?'Fechar caixa':'Abrir atendimento',current?'wallet':'sun','button subtle'):''}${btn('menu-qr','QR do cardápio','qr','button subtle')}</div></div>${connectionError?`<p class="notice warning">Sem atualização: ${e(connectionError)}. Os últimos dados recebidos continuam na tela.</p>`:''}${content}</main><footer class="staff-footer">ESPAÇO CAFÉ · PAES CABO<span>Servir bem, do primeiro pedido à última entrega.</span></footer></div></div>`;}
function metric(label,value,ic,note='',cls=''){return `<article class="metric ${cls}"><div><span>${label}</span>${icon(ic)}</div><strong>${value}</strong><small>${note}</small></article>`;}
function renderDashboard(){const t=totals(snapshot),session=snapshot.sessions.find(s=>s.id===snapshot.session_id),live=snapshot.orders.filter(o=>o.payment_status==='paid'&&!['delivered','cancelled'].includes(o.status));staffShell(`<section class="welcome-banner"><div><span class="eyebrow">GENTE, CAFÉ & BOAS CONVERSAS</span><h2>Um bom encontro<br>começa nos detalhes.</h2><p>${e(session?.title||'Tudo pronto para o próximo domingo?')} · acompanhe o cuidado acontecendo.</p><a href="/caixa" data-nav class="button lime">Registrar um pedido ${icon('plus')}</a></div><div class="welcome-art">${icon('coffee')}<span>com carinho,<br><em>em cada pedido.</em></span></div></section><div class="metrics">${metric('Vendas recebidas',money(t.revenue),'wallet',`${t.paid} pedidos pagos no atendimento`,'accent')}${metric('Aguardando pagamento',money(t.pending_cents),'clock',`${t.pending} comandas pendentes`)}${metric('Na cozinha',t.active,'chef','Pedidos pagos em andamento')}${metric('Ticket médio',money(t.ticket),'chart','Por pedido pago, sem cancelados')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-title"><h3>A cozinha está em movimento.</h3><a href="/cozinha" data-nav>Ver cozinha ${icon('arrow')}</a></div><div class="mini-columns">${['queued','ready'].map(s=>`<div><span class="eyebrow">${STATUS[s]} <b>${live.filter(o=>s==='queued'?['queued','preparing'].includes(o.status):o.status===s).length}</b></span>${live.filter(o=>s==='queued'?['queued','preparing'].includes(o.status):o.status===s).slice(0,3).map(o=>`<button type="button" data-action="order" data-id="${o.id}" class="mini-order"><strong>#${number(o.number)}</strong><span>${e(o.customer_name)}</span><small>${age(o.created_at)} min</small></button>`).join('')||'<p class="muted">Tudo em dia por aqui.</p>'}</div>`).join('')}</div></section><section class="panel low-stock"><div class="panel-title"><h3>De olho na despensa.</h3>${icon('box')}</div>${snapshot.products.filter(p=>p.active&&p.stock<=p.low_stock).slice(0,5).map(p=>`<div class="line-item"><span>${e(p.name)}</span>${tag(p.stock+' un.',p.stock?'pending':'refunded')}</div>`).join('')||empty('Estoque em dia.','Os itens estão acima do alerta.','check')}<a href="/estoque" data-nav class="text-button">Cuidar do estoque ${icon('arrow')}</a></section></div><div class="bottom-tip">${icon('heart')} A cozinha recebe apenas pedidos pagos. Assim, o caixa e o preparo caminham juntos.</div>`,'Boa noite, equipe<span class="brand-dot">.</span>');}
function renderPOS(){staffShell(`<div class="pos-layout"><section>${filters()}<div id="product-grid" class="product-grid pos-products">${productGrid(true)}</div></section><aside class="panel pos-basket"><div class="panel-title"><h3>Comanda do balcão</h3>${icon('receipt')}</div><div id="pos-basket">${basketHTML(true)}</div></aside></div>`,'Uma nova comanda<span class="brand-dot">.</span>','ESCOLHA · REGISTRE · RECEBA');}
function visibleOrders(){return snapshot.orders.filter(o=>(orderFilter==='todos'||(orderFilter==='pending'?o.payment_status==='pending'&&o.status!=='cancelled':orderFilter==='queued'?o.payment_status==='paid'&&['queued','preparing'].includes(o.status):o.status===orderFilter))&&(`${o.number} ${o.customer_name}`.toLowerCase().includes(orderSearch.toLowerCase())));}
function orderRows(){const list=visibleOrders();return list.length?`<div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Retirada</th><th>Itens</th><th>Pagamento</th><th>Etapa</th><th>Total</th><th></th></tr></thead><tbody>${list.map(o=>`<tr><td><strong>#${number(o.number)}</strong><small>${time(o.created_at)} · ${o.source==='web'?'Online':'Balcão'}</small></td><td>${e(o.customer_name)}</td><td>${o.items.reduce((n,i)=>n+i.quantity,0)} itens</td><td>${payTag(o)}</td><td>${statusTag(o)}</td><td>${money(o.total_cents)}</td><td>${btn('order','Abrir','arrow','button compact subtle',`data-id="${o.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma comanda nesta seleção.','Registre um pedido ou ajuste os filtros.','receipt');}
function renderOrders(){staffShell(`<div class="catalog-tools"><div class="pills">${[['todos','Todos'],['pending','Falta pagar'],['queued','A preparar'],['ready','Prontos'],['delivered','Entregues'],['cancelled','Cancelados']].map(([k,v])=>`<button class="pill ${k===orderFilter?'active':''}" type="button" data-action="order-filter" data-filter="${k}">${v}</button>`).join('')}</div><label class="search">${icon('search')}<input id="order-search" type="search" placeholder="Nome ou senha" value="${e(orderSearch)}" aria-label="Buscar pedido"></label></div><section class="panel" id="order-table">${orderRows()}</section><p class="muted">Pedidos pendentes reservam estoque. Revise pedidos antigos e cancele os abandonados para liberar as unidades.</p>`,'Cada pedido, no seu lugar<span class="brand-dot">.</span>');}
function renderKitchen(){staffShell(`<div class="kitchen-toolbar"><p>${icon('chef')} Pedidos pagos aparecem aqui. Toque em Pronto quando terminar.</p>${btn('sound',sound?'Som ativado':'Ativar aviso sonoro',sound?'volume':'mute','button subtle')}</div>${kitchenBoard(snapshot.orders)}<p class="muted kitchen-info">Quando o cliente retirar, o caixa confirma a entrega em Pedidos.</p>`,'Tem cuidado saindo<span class="brand-dot">.</span>','COZINHA AO VIVO · DO CAIXA PARA CÁ');}
function renderStock(){staffShell(`<div class="stock-heading"><p>Preços, disponibilidade e quantidade, no mesmo lugar.</p>${btn('new-product','Adicionar alimento','plus','button lime')}</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Alimento</th><th>Categoria</th><th>Preço</th><th>Estoque</th><th>No cardápio</th><th>Ações</th></tr></thead><tbody>${snapshot.products.map(p=>`<tr><td><div class="table-product"><img src="${e(safeImage(p.image_url,p.category))}" alt=""><div><strong>${e(p.name)}</strong><small>${p.featured?'Destaque da casa':p.prep_minutes+' min de preparo'}</small></div></div></td><td>${e(p.category)}</td><td>${money(p.price_cents)}</td><td>${tag(p.stock+' un.',p.stock<=p.low_stock?'pending':'paid')}</td><td>${tag(p.active?'Visível':'Oculto',p.active?'paid':'')}</td><td><div class="row-actions">${btn('edit-product','Editar','edit','button compact subtle',`data-id="${p.id}"`)}${btn('stock','Ajustar estoque','box','button compact subtle',`data-id="${p.id}"`)}</div></td></tr>`).join('')}</tbody></table></div>${snapshot.products.length?'':empty('Seu cardápio começa aqui.','Adicione os alimentos do próximo encontro.','coffee')}</section><div class="dashboard-grid"><section class="panel"><h3>Últimos ajustes de estoque</h3>${snapshot.stock_moves.slice(0,12).map(m=>`<div class="line-item"><span>${e(snapshot.products.find(p=>p.id===m.product_id)?.name||'Produto')}<small>${e(m.reason)} · ${time(m.created_at)}</small></span><strong>${m.delta>0?'+':''}${m.delta}</strong></div>`).join('')||'<p class="muted">Sem movimentações por enquanto.</p>'}</section><section class="panel"><h3>Uma despensa organizada.</h3><p>O estoque baixa quando o pedido é registrado. Ao cancelar uma comanda, as unidades voltam automaticamente.</p><p class="muted">Combos são produtos com estoque próprio. Separe a quantidade dos combos dos itens avulsos para não contar o mesmo alimento duas vezes.</p></section></div>`,'O cardápio está nas suas mãos<span class="brand-dot">.</span>');}
function renderReports(){const t=totals(snapshot),s=snapshot.sessions.find(s=>s.id===snapshot.session_id);staffShell(`<div class="report-filter"><label class="field">Atendimento<select id="session-select"><option value="">Selecione</option>${snapshot.sessions.map(s=>`<option value="${s.id}" ${s.id===snapshot.session_id?'selected':''}>${e(s.title)} · ${date(s.opened_at)} · ${s.state==='open'?'Aberto':'Fechado'}</option>`).join('')}</select></label>${btn('export','Exportar vendas CSV','download','button subtle')}${btn('cash-move','Entrada ou sangria','wallet','button subtle',snapshot.sessions.some(s=>s.state==='open')?'':'disabled')}</div><div class="metrics">${metric('Vendas líquidas',money(t.revenue),'chart',`${t.paid} pedidos pagos · ${t.cancelled} cancelados`,'accent')}${metric('Dinheiro esperado',money(s?.expected_cash_cents??t.expected),'wallet','Abertura + vendas em dinheiro + entradas − saídas')}${metric('Pendências',money(t.pending_cents),'clock',`${t.pending} pedidos aguardando pagamento`)}${metric('Conferência do caixa',s?.state==='closed'?money(s.counted_cash_cents-s.expected_cash_cents):'Em aberto','check',s?.state==='closed'?'Contado menos esperado':'Conferir dinheiro ao encerrar')}</div><div class="dashboard-grid"><section class="panel"><h3>Recebimento por meio</h3>${Object.entries(METHODS).map(([k,v])=>`<div class="method-row"><span>${v}</span><strong>${money(t.methods[k])}</strong><div class="bar"><i style="width:${t.revenue?Math.max(0,t.methods[k]/t.revenue*100):0}%"></i></div></div>`).join('')}<p class="muted">Pix e cartão são conferidos pela equipe. Devoluções já são descontadas.</p></section><section class="panel"><h3>Os favoritos do encontro.</h3>${t.ranking.slice(0,6).map((p,i)=>`<div class="line-item"><span><b class="rank">${i+1}</b> ${e(p.name)}</span><strong>${p.quantity} un.</strong></div>`).join('')||'<p class="muted">Os mais pedidos aparecem depois das primeiras vendas.</p>'}</section><section class="panel"><h3>Entradas e sangrias</h3>${snapshot.cash_moves.map(m=>`<div class="line-item"><span>${e(m.reason)}<small>${date(m.created_at)}</small></span><strong>${m.direction==='entrada'?'+':'−'} ${money(m.amount_cents)}</strong></div>`).join('')||'<p class="muted">Nenhuma entrada extra ou sangria.</p>'}</section><section class="panel"><h3>Fechamento do atendimento</h3>${s?`<div class="line-item"><span>Fundo de abertura</span><strong>${money(s.opening_cash_cents)}</strong></div><div class="line-item"><span>Dinheiro contado</span><strong>${s.counted_cash_cents!=null?money(s.counted_cash_cents):'A conferir'}</strong></div><p class="muted">${e(s.closing_note||'O fechamento registra o total contado e a diferença. Os pedidos em aberto precisam ser resolvidos antes.')}</p>`:'<p class="muted">Abra o primeiro atendimento.</p>'}</section></div>`,'O encontro em números<span class="brand-dot">.</span>');}
function renderTeam(){staffShell(`<div class="stock-heading"><p>Cada voluntário com seu acesso e sua função.</p>${btn('new-staff','Autorizar pessoa','users','button lime')}</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>E-mail</th><th>Perfil</th><th>Acesso</th><th></th></tr></thead><tbody>${snapshot.staff.map(s=>`<tr><td>${e(s.email)}</td><td>${ROLES[s.role]}</td><td>${tag(s.active?'Ativo':'Desativado',s.active?'paid':'')}</td><td>${btn('edit-staff','Alterar','edit','button compact subtle',`data-email="${e(s.email)}"`)}</td></tr>`).join('')}</tbody></table></div></section><div class="role-grid">${[['admin','Administra cardápio, estoque, equipe e configurações. Também opera caixa e cozinha.'],['caixa','Registra pedidos, confirma pagamentos, cancela, entrega e fecha o caixa.'],['cozinha','Vê os pedidos pagos e atualiza preparo, pronto e entrega.']].map(([r,t])=>`<article class="panel"><h3>${ROLES[r]}</h3><p>${t}</p></article>`).join('')}</div><p class="notice">Crie e confirme cada pessoa em Authentication → Users no Supabase. Depois autorize o mesmo e-mail aqui. A senha deve ser individual.</p>`,'Quem serve com a gente<span class="brand-dot">.</span>');}
function renderSettings(){const s=snapshot.settings;staffShell(`<form id="settings-form" class="panel settings-form"><h3>O jeito da nossa mesa.</h3><div class="form-grid"><label class="field">Nome do espaço<input name="title" required minlength="2" maxlength="80" value="${e(s.title)}"></label><label class="field">Mensagem do cardápio<input name="message" maxlength="200" value="${e(s.message)}"></label></div><label class="toggle-line"><input name="public_ordering" type="checkbox" ${s.public_ordering?'checked':''}><span><strong>Permitir pedidos pelo celular</strong><small>Também precisa existir um caixa aberto. O cliente não confirma o próprio pagamento.</small></span></label><h3>Pix no pedido</h3><p class="muted">Opcional. O QR Code é de cobrança estática. Confira os dados do favorecido e o recebimento no aplicativo bancário.</p><div class="form-grid"><label class="field">Chave Pix<input name="pix_key" maxlength="100" value="${e(s.pix_key)}" placeholder="Chave aleatória, CPF/CNPJ, e-mail ou telefone"></label><label class="field">Nome do recebedor<input name="pix_name" maxlength="25" value="${e(s.pix_name)}"></label><label class="field">Cidade<input name="pix_city" maxlength="15" value="${e(s.pix_city)}"></label></div><p class="notice">A chave Pix cadastrada fica visível aos clientes. Ela não é uma chave de acesso do Supabase. Não coloque senhas ou dados de acesso bancário.</p><button class="button lime" type="submit">Salvar configurações ${icon('check')}</button><p class="form-error" role="alert" hidden></p></form><section class="panel audit"><h3>Últimas atividades</h3>${snapshot.audit.slice(0,12).map(a=>`<div class="line-item"><span>${e(a.action.replaceAll('_',' '))}<small>${e(a.detail)}</small></span><small>${date(a.created_at)}</small></div>`).join('')||'<p class="muted">As operações ficarão registradas aqui.</p>'}</section>`,'Os detalhes fazem a diferença<span class="brand-dot">.</span>');}
function renderStaff(){if(!snapshot)return;({'/admin':renderDashboard,'/caixa':renderPOS,'/pedidos':renderOrders,'/cozinha':renderKitchen,'/estoque':renderStock,'/relatorios':renderReports,'/equipe':renderTeam,'/configuracoes':renderSettings}[path()]||renderDashboard)();}

function renderLogin(){app.innerHTML=`${banner()}<main id="main" class="login-layout"><section class="login-story">${brand()}<div><span class="eyebrow">PAES CABO · NOSSA EQUIPE</span><h1>Servir é<br>colocar <em>amor</em><br>nos detalhes.</h1><p>Do caixa à cozinha,<br>o cuidado acontece junto.</p></div><span class="login-coffee">${icon('coffee')}</span></section><section class="login-form"><a href="/" data-nav class="back-link">← Voltar ao cardápio</a><span class="eyebrow">BOM TER VOCÊ POR AQUI</span><h2>Vamos cuidar<br>desse encontro?</h2><p class="muted">Entre com o acesso da equipe.</p>${demo?`<p class="notice">Demonstração local. Escolha um perfil para experimentar. Não usa senhas reais.</p><div class="demo-roles">${Object.entries(ROLES).map(([k,v])=>btn('demo-login',v,'arrow','button subtle full',`data-role="${k}"`)).join('')}</div>`:`<form id="login-form"><label class="field">Seu e-mail<input name="email" type="email" autocomplete="username" required placeholder="equipe@exemplo.com"></label><label class="field">Senha<input name="password" type="password" autocomplete="current-password" required minlength="6"></label><p class="form-error" role="alert" hidden></p><button class="button lime full" type="submit">Entrar no espaço ${icon('arrow')}</button>${btn('forgot','Esqueci minha senha','','text-button')}</form>`}<small class="muted">Seu acesso é pessoal. O perfil define o que você pode fazer.</small></section></main>`;}
function orderDetails(id){const o=snapshot.orders.find(o=>o.id===id);if(!o)return;dialog('Pedido #'+number(o.number),`<div class="order-detail-top"><h3>${e(o.customer_name)}</h3><div>${payTag(o)} ${statusTag(o)}</div><small>${date(o.created_at)} · ${o.source==='web'?'Pelo celular':'No balcão'}</small></div>${o.items.map(i=>`<div class="line-item"><span>${i.quantity} × ${e(i.name)}</span><strong>${money(i.quantity*i.price_cents)}</strong></div>`).join('')}${discountSummary(o)}<div class="basket-summary">Total <strong>${money(o.total_cents)}</strong></div>${o.notes?`<p class="notice">${e(o.notes)}</p>`:''}<div class="detail-actions">${o.payment_status==='pending'&&o.status!=='cancelled'?btn('pay','Confirmar pagamento','wallet','button lime full',`data-id="${o.id}"`):''}${o.payment_status==='paid'&&nextStatus(o.status)?btn('advance',nextLabel(o.status),'arrow','button lime full',`data-id="${o.id}" data-status="${nextStatus(o.status)}"`):''}${btn('print',o.payment_status==='paid'?'Imprimir recibo':'Imprimir comanda','receipt','button subtle full',`data-id="${o.id}"`)}${o.status!=='cancelled'?btn('cancel','Cancelar pedido','close','button danger full',`data-id="${o.id}"`):`<p class="notice">${e(o.cancel_reason)}</p>`}</div>`);}
function payDialog(id){const o=snapshot.orders.find(o=>o.id===id);dialog('Confirmar pagamento',`<p>Pedido <strong>#${number(o.number)}</strong> · ${e(o.customer_name)}</p><div class="line-item"><span>Subtotal</span><strong>${money(o.total_cents)}</strong></div><label class="field">Como o cliente pagou?<select name="method" id="checkout-method">${Object.entries(METHODS).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label>${discountFields()}<label class="check-line"><input type="checkbox" required name="confirmed">Conferi o recebimento real do pagamento.</label>`,async f=>{const method=f.get('method');await api('cafe_pay_order_discount',{p_id:id,p_method:method,p_received:method==='dinheiro'?cents(f.get('received')):null,p_discount:discountCents(f.get('discount'),o.total_cents)});dismiss();await refreshStaff();toast('Pagamento confirmado. Pedido liberado para a cozinha.');},'Confirmar pagamento');setupDiscount(o.total_cents,{autofill:true});}
function cancelDialog(id){const o=snapshot.orders.find(o=>o.id===id);dialog('Cancelar pedido #'+number(o.number),`<p>${e(o.customer_name)} · ${money(o.total_cents)}</p><label class="field">Motivo do cancelamento<textarea name="reason" minlength="3" maxlength="200" required rows="2"></textarea></label>${o.payment_status==='paid'?'<p class="notice warning">Faça a devolução real antes de confirmar. Este sistema registra a devolução, mas não transfere dinheiro pelo banco nem estorna a maquininha.</p><label class="check-line"><input type="checkbox" name="refund" required>Já devolvi o valor ao cliente.</label>':'<p class="notice">As unidades reservadas voltarão ao estoque.</p>'}`,async f=>{await api('cafe_cancel_order',{p_id:id,p_reason:f.get('reason'),p_refund_confirmed:f.get('refund')==='on'});dismiss();await refreshStaff();toast('Pedido cancelado e estoque devolvido.');},'Confirmar cancelamento');}
function productDialog(id){const p=snapshot.products.find(p=>p.id===id)||{name:'',category:'Salgados',description:'',allergens:'',price_cents:0,low_stock:5,prep_minutes:5,active:true,featured:false,image_url:''};dialog(id?'Editar alimento':'Um novo favorito',`<div class="form-grid"><label class="field">Nome<input name="name" required minlength="2" maxlength="120" value="${e(p.name)}"></label><label class="field">Categoria<select name="category">${CATEGORIES.map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">Preço (R$)<input name="price" required inputmode="decimal" value="${p.price_cents?priceInput(p.price_cents):''}" placeholder="7,00"></label><label class="field">Preparo (minutos)<input name="prep" type="number" min="0" max="120" value="${p.prep_minutes}" required></label><label class="field">Alerta de estoque baixo<input name="low" type="number" min="0" max="100000" value="${p.low_stock}" required></label><label class="field">Foto do alimento<input name="photo" type="file" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG ou WebP de até 5 MB.</small></label></div><label class="field">Descrição<textarea name="description" maxlength="1000" rows="2">${e(p.description)}</textarea></label><label class="field">Ingredientes e alergênicos<textarea name="allergens" maxlength="300" rows="2" placeholder="Preencha conforme a receita real.">${e(p.allergens)}</textarea></label><label class="check-line"><input name="active" type="checkbox" ${p.active?'checked':''}>Visível no cardápio</label><label class="check-line"><input name="featured" type="checkbox" ${p.featured?'checked':''}>Destaque da casa</label><p class="notice">O estoque é ajustado pelo botão “Ajustar estoque”. Novos alimentos começam com zero unidades.</p>`,async f=>{const file=f.get('photo');let image=p.image_url;if(file?.size)image=await upload(file);await api('cafe_save_product',{p:{id:id||null,name:f.get('name'),category:f.get('category'),price_cents:cents(f.get('price')),description:f.get('description'),allergens:f.get('allergens'),low_stock:Number(f.get('low')),prep_minutes:Number(f.get('prep')),active:f.get('active')==='on',featured:f.get('featured')==='on',image_url:demo&&image?.startsWith('blob:')?p.image_url||'':image}});dismiss();await refreshStaff();toast(id?'Alimento atualizado.':'Alimento criado. Agora ajuste a quantidade em estoque.');});}
function stockDialog(id){const p=snapshot.products.find(p=>p.id===id);dialog('Cuidar do estoque',`<h3>${e(p.name)}</h3><p>Disponível agora: <strong>${p.stock} unidades</strong></p><div class="form-grid"><label class="field">Operação<select name="direction"><option value="1">Adicionar / repor</option><option value="-1">Retirar / perda</option></select></label><label class="field">Quantidade<input name="quantity" type="number" min="1" max="100000" required></label></div><label class="field">Motivo<input name="reason" required minlength="3" maxlength="200" placeholder="Ex.: produção do domingo"></label>`,async f=>{await api('cafe_adjust_stock',{p_id:id,p_delta:Number(f.get('direction'))*Number(f.get('quantity')),p_reason:f.get('reason')});dismiss();await refreshStaff();toast('Estoque atualizado.');});}
function staffDialog(email){const s=snapshot.staff.find(s=>s.email===email)||{email:'',role:'caixa',active:true};dialog('Acesso da equipe',`<p class="notice">Primeiro crie e confirme a conta em Authentication → Users no Supabase. Depois informe o mesmo e-mail.</p><label class="field">E-mail<input name="email" type="email" required value="${e(s.email)}"></label><label class="field">Perfil<select name="role">${Object.entries(ROLES).map(([k,v])=>`<option value="${k}" ${s.role===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="check-line"><input name="active" type="checkbox" ${s.active?'checked':''}>Acesso ativo</label>`,async f=>{await api('cafe_set_staff',{p_email:f.get('email'),p_role:f.get('role'),p_active:f.get('active')==='on'});dismiss();await refreshStaff();toast('Acesso atualizado.');});}
function openSession(){dialog('Abrir o nosso encontro',`<label class="field">Nome do atendimento<input name="title" required minlength="3" maxlength="100" value="Culto de domingo"></label><label class="field">Fundo de caixa em dinheiro (R$)<input name="opening" required inputmode="decimal" value="0,00"></label><p class="notice">O fundo é o dinheiro para troco. Ele não conta como venda. Confira estoque e preços antes de abrir os pedidos online.</p>`,async f=>{await api('cafe_open_session',{p_title:f.get('title'),p_opening:cents(f.get('opening'),{zero:true})});selectedSession=null;dismiss();await refreshStaff();toast('Atendimento aberto.');},'Abrir atendimento');}
function closeSession(){const s=snapshot.sessions.find(s=>s.state==='open');if(!s)return;dialog('Fechar o caixa',`<p>${e(s.title)}</p><label class="field">Dinheiro contado na gaveta (R$)<input name="counted" required inputmode="decimal" placeholder="Conte antes de consultar o esperado"></label><label class="field">Observação<textarea name="note" maxlength="500" rows="2" placeholder="Ex.: diferença ou informação para a próxima equipe"></textarea></label><p class="notice">Os pedidos precisam estar entregues ou cancelados. Pix e cartão não entram na contagem da gaveta.</p>`,async f=>{const r=await api('cafe_close_session',{p_id:s.id,p_counted:cents(f.get('counted'),{zero:true}),p_note:f.get('note')});dismiss();await refreshStaff();dialog('Atendimento encerrado',`<div class="line-item"><span>Dinheiro esperado</span><strong>${money(r.expected)}</strong></div><div class="line-item"><span>Dinheiro contado</span><strong>${money(r.counted)}</strong></div><div class="line-item"><span>Diferença</span><strong>${money(r.difference)}</strong></div><p class="muted">O histórico fica em Caixa e relatórios.</p>`);},'Encerrar atendimento');}
function cashDialog(){dialog('Movimentar dinheiro',`<label class="field">Tipo<select name="direction"><option value="entrada">Entrada extra / suprimento</option><option value="saida">Saída / sangria</option></select></label><label class="field">Valor (R$)<input name="amount" inputmode="decimal" required></label><label class="field">Motivo<input name="reason" minlength="3" maxlength="200" required placeholder="Ex.: compra emergencial de gelo"></label><p class="notice">Registre a movimentação real. Isto não é uma venda.</p>`,async f=>{await api('cafe_cash_move',{p_direction:f.get('direction'),p_amount:cents(f.get('amount')),p_reason:f.get('reason')});dismiss();await refreshStaff();toast('Movimentação registrada.');});}
async function showMenuQR(){const link=location.origin+'/';const data=await QRCode.toDataURL(link,{width:320,margin:2,color:{dark:'#24163d',light:'#ffffff'}});dialog('Uma mesa na palma da mão.',`<div class="qr-display"><img src="${data}" alt="QR Code para abrir o cardápio"><p>Aponte a câmera e faça seu pedido.</p><p class="muted">${e(link)}</p>${btn('copy-menu','Copiar link','link','button lime full')}<a class="button subtle full" href="${data}" download="qr-cardapio-paes-cabo.png">Baixar QR Code ${icon('download')}</a></div>`);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copiado.');}catch{dialog('Copie este conteúdo',`<label class="field">Selecione e copie<textarea readonly rows="4">${e(text)}</textarea></label>`);}}
function exportReport(){const rows=[['pedido','nome','criado_em','pagamento','etapa','meio','total_reais','venda_liquida_reais','itens','desconto_reais']];for(const o of snapshot.orders)rows.push([number(o.number),o.customer_name,date(o.created_at),PAYMENT[o.payment_status],STATUS[o.status],METHODS[o.payment_method]||'',priceInput(o.total_cents),priceInput(o.payment_status==='paid'&&o.status!=='cancelled'?o.total_cents:0),o.items.map(i=>`${i.quantity} x ${i.name}`).join(' | '),priceInput(o.discount_cents)]);const blob=new Blob([csvText(rows)],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='espaco-cafe-vendas.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000);}

function beep(){if(!sound||!audio)return;try{const osc=audio.createOscillator(),gain=audio.createGain();osc.connect(gain);gain.connect(audio.destination);osc.frequency.value=660;gain.gain.setValueAtTime(.06,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.3);osc.start();osc.stop(audio.currentTime+.3);}catch{}}
async function refreshStaff({quiet=false}={}){const p=path(),sequence=++refreshSequence;try{const next=await api('cafe_staff_state',{p_session:selectedSession});if(sequence!==refreshSequence||p!==path())return;const paid=new Set(next.orders.filter(o=>o.payment_status==='paid').map(o=>o.id));if(knownPaid&&[...paid].some(id=>!knownPaid.has(id))){beep();toast('Novo pedido pago na cozinha.');}knownPaid=paid;snapshot=next;if(user)user.role=next.role;lastSync=new Date().toISOString();connectionError='';const allowed=navItems.find(i=>i[0]===path());if(user&&allowed&&!allowed[3].includes(user.role)){await go(user.role==='cozinha'?'/cozinha':user.role==='caixa'?'/caixa':'/admin');return;}if(isStaff()&&(!quiet||(!busy&&!modal&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))))renderStaff();}catch(err){if(sequence!==refreshSequence||p!==path())return;connectionError=friendly(err);if(!quiet)throw err;if(isStaff()&&!modal&&!busy)renderStaff();}}
async function refreshCurrent(){if(isStaff())return refreshStaff();if(path()==='/pedido'){const token=new URLSearchParams(location.hash.slice(1)).get('token');tracked=token?await api('cafe_track',{p_token:token}):null;lastSync=new Date().toISOString();connectionError='';renderTrack();}else if(path()==='/retirada'){publicBoard=await api('cafe_board');lastSync=new Date().toISOString();connectionError='';renderBoard();}else if(path()==='/'){menu=await api('cafe_menu');lastSync=new Date().toISOString();refreshMenuGrid();}}
function renderSetup(){app.innerHTML=`<main id="main" class="setup-screen">${brand()}<div class="panel"><span class="eyebrow">VAMOS COLOCAR O CAFÉ NO AR</span><h1>Falta conectar<br>o nosso espaço.</h1><p>Configure VITE_SUPABASE_URL e VITE_SUPABASE_PUBLISHABLE_KEY na Vercel e publique novamente.</p><p class="muted">O guia COMECE-AQUI.html que acompanha o projeto explica cada etapa. Nenhum pedido ou pagamento foi registrado nesta tela.</p></div></main>`;}
async function route(){const serial=++routeSerial;clearInterval(poll);unsubscribe?.();unsubscribe=null;if(path()!=='/relatorios')selectedSession=null;dismiss();app.innerHTML='<div class="loading"><span class="loader"></span>Preparando nosso encontro…</div>';document.title='Espaço Café · PAES Cabo';if(!configured&&!demo){renderSetup();return;}
 try{
 if(isStaff()){
  user=await currentUser();if(serial!==routeSerial)return;if(!user){history.replaceState(null,'','/login');renderLogin();return;}
  const nav=navItems.find(i=>i[0]===path());if(!nav?.[3].includes(user.role)){history.replaceState(null,'',user.role==='cozinha'?'/cozinha':user.role==='caixa'?'/caixa':'/admin');}
  await refreshStaff();unsubscribe=subscribe(()=>{if(!busy)setTimeout(()=>refreshStaff({quiet:true}),450);});poll=setInterval(()=>refreshStaff({quiet:true}),15000);
 }else if(path()==='/login'){renderLogin();}
 else if(path()==='/nova-senha'){app.innerHTML=`<main id="main" class="container narrow">${brand()}<form id="password-form" class="panel"><h1>Uma nova senha.</h1><label class="field">Senha com pelo menos 8 caracteres<input name="password" type="password" minlength="8" autocomplete="new-password" required></label><p class="form-error" hidden></p><button class="button lime">Salvar nova senha</button></form></main>`;}
 else{menu=await api('cafe_menu');if(serial!==routeSerial)return;if(path()==='/pedido'||path()==='/retirada'){await refreshCurrent();poll=setInterval(async()=>{if(modal)return;try{await refreshCurrent();}catch(err){connectionError=friendly(err);path()==='/pedido'?renderTrack():renderBoard();}},6000);}else{if(path()!=='/')history.replaceState(null,'','/');renderMenu();poll=setInterval(async()=>{try{menu=await api('cafe_menu');if(!busy&&!modal)refreshMenuGrid();}catch{}},30000);}}
 }catch(err){app.innerHTML=`<main id="main" class="container narrow">${brand()}${empty('Não conseguimos abrir o espaço agora.',e(friendly(err)),'alert')}${btn('retry','Tentar novamente','refresh','button lime')}<a class="button subtle" href="/" data-nav>Voltar ao cardápio</a></main>`;}}

document.addEventListener('click',async ev=>{
 const a=ev.target.closest('a[data-nav]');if(a&&!ev.ctrlKey&&!ev.metaKey&&!ev.shiftKey){ev.preventDefault();await go(a.getAttribute('href'));return;}
 const b=ev.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action,id=b.dataset.id;
 try{
 if(action==='dismiss'){if(!busy)dismiss();return;}
 if(action==='retry'){await route();return;}
 if(action==='category'){category=b.dataset.category;refreshMenuGrid();return;}
 if(action==='order-filter'){orderFilter=b.dataset.filter;renderOrders();return;}
 if(action==='add'||action==='minus'){const pos=path()==='/caixa',basket=pos?staffCart:cart,p=(pos?snapshot.products:menu.products).find(p=>p.id===id);const next=(basket[id]||0)+(action==='add'?1:-1);if(next>Math.min(p.stock,20))throw Error('Limite disponível para esse alimento.');if(next>0)basket[id]=next;else delete basket[id];if(!pos)saveCart();refreshMenuGrid();if(modal&&path()!=='/caixa')openCart();return;}
 if(action==='cart'){openCart();return;}
 if(action==='checkout'||action==='counter-checkout'){await checkout(action==='counter-checkout');return;}
 if(action==='ingredients'){const p=(path()==='/caixa'?snapshot.products:menu.products).find(p=>p.id===id);if(!p)throw Error('PRODUTO_INDISPONIVEL');dialog(e(p.name),`<p>${e(p.description)}</p><h3>Ingredientes e alergênicos</h3><p>${e(p.allergens||'A equipe ainda não informou os ingredientes. Confirme no balcão antes de pedir, principalmente se houver alergia ou restrição alimentar.')}</p>`);return;}
 if(action==='order'){orderDetails(id);return;}
 if(action==='pay'){payDialog(id);return;}
 if(action==='cancel'){cancelDialog(id);return;}
 if(action==='advance'){await act(b,async()=>{await api('cafe_advance_order',{p_id:id,p_status:b.dataset.status});dismiss();await refreshStaff();toast(b.dataset.status==='ready'?'Pedido pronto para retirar.':b.dataset.status==='delivered'?'Entrega confirmada.':'Etapa atualizada.');});return;}
 if(action==='print'||action==='print-track'){printReceipt(action==='print-track'?tracked:snapshot.orders.find(o=>o.id===id),snapshot?.settings||menu.settings,demo);return;}
 if(action==='share-order'){await copy(location.origin+'/pedido#token='+tracked.token);return;}
 if(action==='menu-qr'){await showMenuQR();return;}
 if(action==='copy-menu'){await copy(location.origin+'/');return;}
 if(action==='refresh'){await act(b,refreshCurrent);return;}
 if(action==='new-product'||action==='edit-product'){productDialog(id);return;}
 if(action==='stock'){stockDialog(id);return;}
 if(action==='new-staff'||action==='edit-staff'){staffDialog(b.dataset.email);return;}
 if(action==='open-session'){openSession();return;}
 if(action==='close-session'){closeSession();return;}
 if(action==='cash-move'){cashDialog();return;}
 if(action==='export'){exportReport();return;}
 if(action==='fullscreen'){if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();return;}
 if(action==='sound'){sound=!sound;if(sound){audio??=new(window.AudioContext||window.webkitAudioContext)();await audio.resume();beep();}renderKitchen();return;}
 if(action==='demo-login'){sessionStorage.setItem('cafe-demo-role',b.dataset.role);user=await currentUser();await go(user.role==='cozinha'?'/cozinha':user.role==='caixa'?'/caixa':'/admin');return;}
 if(action==='logout'){await logout();user=null;await go('/login');return;}
 if(action==='reset-demo'){demoReset();snapshot=null;await route();return;}
 if(action==='forgot'){dialog('Recuperar seu acesso',`<label class="field">E-mail da equipe<input name="email" type="email" required></label>`,async f=>{const {error}=await db.auth.resetPasswordForEmail(f.get('email'),{redirectTo:location.origin+'/nova-senha'});if(error)throw error;toast('Se houver uma conta, enviaremos as instruções por e-mail.');},'Enviar instruções');return;}
 }catch(err){toast(friendly(err),true);}
});
document.addEventListener('input',ev=>{if(ev.target.id==='menu-search'){search=ev.target.value;refreshMenuGrid();}if(ev.target.id==='order-search'){orderSearch=ev.target.value;document.querySelector('#order-table').innerHTML=orderRows();}});
document.addEventListener('change',async ev=>{if(ev.target.id==='checkout-method'){const f=document.querySelector('#received-field');if(f)f.hidden=ev.target.value!=='dinheiro';const c=document.querySelector('#change-value');if(c)c.hidden=ev.target.value!=='dinheiro';}if(ev.target.id==='session-select'){selectedSession=ev.target.value||null;await act(null,refreshStaff);}});
document.addEventListener('submit',async ev=>{if(!['login-form','settings-form','password-form'].includes(ev.target.id))return;ev.preventDefault();const form=ev.target,button=form.querySelector('[type=submit]')||form.querySelector('button'),f=new FormData(form),err=form.querySelector('.form-error');if(busy)return;busy=true;button.disabled=true;err.hidden=true;try{if(form.id==='login-form'){user=await login(f.get('email'),f.get('password'));busy=false;await go(user.role==='cozinha'?'/cozinha':user.role==='caixa'?'/caixa':'/admin');}else if(form.id==='settings-form'){await api('cafe_save_settings',{p:{title:f.get('title'),message:f.get('message'),pix_key:f.get('pix_key'),pix_name:f.get('pix_name'),pix_city:f.get('pix_city'),public_ordering:f.get('public_ordering')==='on'}});busy=false;await refreshStaff();toast('Configurações salvas.');}else{const {error}=await db.auth.updateUser({password:f.get('password')});if(error)throw error;busy=false;toast('Senha atualizada. Entre com seu acesso.');await go('/login');}}catch(error){err.hidden=false;err.textContent=friendly(error);}finally{busy=false;if(button.isConnected)button.disabled=false;}});
window.addEventListener('popstate',route);
window.addEventListener('offline',()=>{connectionError='Sem internet.';toast('Sem internet. Os pedidos não serão enviados.',true);if(isStaff()&&snapshot)renderStaff();});
window.addEventListener('online',()=>{connectionError='';refreshCurrent().catch(err=>toast(friendly(err),true));});
await route();
